<section class="page-hero page-hero-compact"><div class="container"><span class="eyebrow">YOUR UPDATES</span><h1>Notifications</h1><p>Important updates about your applications, opportunities and account.</p></div></section>
<section class="section"><div class="container"><div class="panel">
    <div class="panel-heading"><div><h2>Your notifications</h2><p><?= e($unreadCount) ?> unread</p></div><?php if ($unreadCount > 0): ?><form method="post" action="<?= e(pageUrl('notifications')) ?>"><?= formToken() ?><input type="hidden" name="action" value="mark_all_notifications_read"><button class="button button-outline button-small" type="submit">Mark all as read</button></form><?php endif; ?></div>
    <?php if ($notifications === []): ?><div class="empty-small"><p>You're all caught up. New updates will appear here.</p></div><?php else: ?><div class="notification-list"><?php foreach ($notifications as $notification): ?><article class="notification-item <?= $notification['read_at'] ? '' : 'unread' ?>"><span class="notification-dot"></span><div><h3><?= e($notification['title']) ?></h3><p><?= e($notification['message']) ?></p><time><?= e(date('M j, Y · g:i a', strtotime($notification['created_at']))) ?></time><?php if (!empty($notification['link'])): ?><a class="text-link" href="<?= e(notificationUrl($notification['link'])) ?>">View details <span aria-hidden="true">→</span></a><?php endif; ?></div><?php if (!$notification['read_at']): ?><form method="post" action="<?= e(pageUrl('notifications')) ?>"><?= formToken() ?><input type="hidden" name="action" value="mark_notification_read"><input type="hidden" name="notification_id" value="<?= e($notification['id']) ?>"><button class="button button-text" type="submit">Mark read</button></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
</div></div></section>
